-- S09 production baseline 2026-10-07. UUIDs pseudonymized. Actual catalogue contracts; production triggers/auth/external FKs excluded.
create table public.assessment_form_items (id uuid default gen_random_uuid(),form_id uuid,item_id uuid,slot_order integer);
create table public.assessment_pools(id uuid default gen_random_uuid(),code text,purpose text,is_protected boolean);
create table public.assessment_forms(id uuid default gen_random_uuid(),code text,pool_id uuid,status text);
create table public.skill_outcomes(skill_id uuid,learning_outcome_id uuid);
create table public.skill_outcome_curriculum_mappings(skill_id uuid,learning_outcome_id uuid,reconciliation_id uuid,mapping_type text,rationale text,created_at timestamptz);
