insert into public.item_options select * from jsonb_populate_recordset(null::public.item_options,'[{"id": "b9a12d5e-6fff-571a-83aa-604d3146c3ee", "item_id": "adb5d4a6-77e1-5a87-a0fb-4d9ed32dc328", "content_en": null, "content_hy": "Սյան բարձրությունը չի փոխվի, քանի որ սպիրտի ծավալը ջերմաստիճանից կախված չէ։", "option_key": "C", "display_order": 3}, {"id": "554d6ef5-7e56-539d-a4b0-57d3c9bc0267", "item_id": "d3e27190-4689-54c0-ad03-f394db0c93d3", "content_en": null, "content_hy": "Տաքանալիս ներսում նոր սպիրտ է առաջանում, և դրա համար սյունը բարձրանում է։", "option_key": "A", "display_order": 1}, {"id": "f2ecf6dc-d7b2-545b-9d48-affc23710ec4", "item_id": "4d7aa791-9955-547d-af22-066d3ea88521", "content_en": null, "content_hy": "Ավելի լայն խողովակում, քանի որ նույն ծավալը լայն խողովակում ավելի մեծ բարձրություն է զբաղեցնում։", "option_key": "A", "display_order": 1}, {"id": "cbfaffba-6b6f-536b-bfae-28e42e7bde12", "item_id": "d3e27190-4689-54c0-ad03-f394db0c93d3", "content_en": null, "content_hy": "Նոր հեղուկ չի առաջանում. սյունը բարձրանում է, որովհետև սպիրտը տաքանալիս սեղմվում է։", "option_key": "B", "display_order": 2}, {"id": "f1fe7acc-6829-56e8-bb9b-5cc131c06042", "item_id": "16b27661-57d7-53df-861d-06b6d5fc86a7", "content_en": null, "content_hy": "Հեղուկը տաքանալիս սեղմվում է, և փոքրացած ծավալը սյունը մղում է վեր։", "option_key": "B", "display_order": 2}, {"id": "fc0ad418-7500-5079-8874-6a58c3a3d8ba", "item_id": "adb5d4a6-77e1-5a87-a0fb-4d9ed32dc328", "content_en": null, "content_hy": "Սյունը կիջնի, քանի որ սառչելիս սպիրտի մի մասը դուրս է գալիս փակ ջերմաչափից։", "option_key": "D", "display_order": 4}, {"id": "e0b1b139-8bba-5efb-875f-caa2875569b5", "item_id": "d3e27190-4689-54c0-ad03-f394db0c93d3", "content_en": null, "content_hy": "Սպիրտի ծավալը չի փոխվում. սանդղակի բաժանումներն են հեղուկը քաշում վեր։", "option_key": "D", "display_order": 4}, {"id": "21f99996-a947-5af7-bca8-3e1f75174397", "item_id": "4d7aa791-9955-547d-af22-066d3ea88521", "content_en": null, "content_hy": "Ավելի նեղ խողովակում, քանի որ նույն ծավալը նեղ խողովակում ավելի մեծ բարձրություն է զբաղեցնում։", "option_key": "D", "display_order": 4}, {"id": "0f1fb35b-dfbb-50ed-a2c9-5432fb11abb4", "item_id": "16b27661-57d7-53df-861d-06b6d5fc86a7", "content_en": null, "content_hy": "Հեղուկը տաքանալիս ընդարձակվում է, և նրա սյունը բարձրանում է մազական խողովակում։", "option_key": "A", "display_order": 1}, {"id": "6d99dc2b-4d33-5fc3-a926-d89da0ff8e32", "item_id": "4d7aa791-9955-547d-af22-066d3ea88521", "content_en": null, "content_hy": "Միայն լայն խողովակում սյունը կբարձրանա, քանի որ նեղ խողովակով հեղուկը չի կարող անցնել։", "option_key": "B", "display_order": 2}, {"id": "01d229fe-bacf-51cc-9019-a8c88a507e34", "item_id": "16b27661-57d7-53df-861d-06b6d5fc86a7", "content_en": null, "content_hy": "Սանդղակի բաժանումները տաքանալիս շարժվում են և հեղուկի սյունը քաշում վեր։", "option_key": "D", "display_order": 4}, {"id": "34f22363-530f-518d-840f-050f39cc5cd2", "item_id": "4d7aa791-9955-547d-af22-066d3ea88521", "content_en": null, "content_hy": "Երկուսում փոփոխությունը նույնը կլինի, քանի որ նույն ծավալի դեպքում խողովակի լայնությունը նշանակություն չունի։", "option_key": "C", "display_order": 3}, {"id": "60afbbf5-4b02-5fc6-a9eb-fe523b398f38", "item_id": "d3e27190-4689-54c0-ad03-f394db0c93d3", "content_en": null, "content_hy": "Նոր հեղուկ չի առաջանում. նույն սպիրտը տաքանալիս ավելի մեծ ծավալ է զբաղեցնում։", "option_key": "C", "display_order": 3}, {"id": "94b8c421-4ab1-5ff4-b7ee-5c50644d623d", "item_id": "adb5d4a6-77e1-5a87-a0fb-4d9ed32dc328", "content_en": null, "content_hy": "Սյունը կբարձրանա, քանի որ սառչելիս սպիրտի ծավալը մեծանում է։", "option_key": "A", "display_order": 1}, {"id": "3be5f1f6-7163-5a7c-99fc-b44081d78abc", "item_id": "16b27661-57d7-53df-861d-06b6d5fc86a7", "content_en": null, "content_hy": "Հեղուկը յուրաքանչյուր չափման ժամանակ եռում է, և գոլորշին սյունը մղում է վեր։", "option_key": "C", "display_order": 3}, {"id": "c31d75f0-1eb9-5cf5-aa1a-4a2169673488", "item_id": "adb5d4a6-77e1-5a87-a0fb-4d9ed32dc328", "content_en": null, "content_hy": "Սյունը կիջնի, քանի որ սառչելիս սպիրտի ծավալը փոքրանում է։", "option_key": "B", "display_order": 2}]'::jsonb);
