insert into public.misconceptions select * from jsonb_populate_recordset(null::public.misconceptions,'[{"id": "bb2794d7-e6d6-5b3f-8828-101935113be9", "code": "thermal_expansion_reversed", "status": "active", "skill_id": "f5205906-522d-5fc8-b4e9-5762abf3109a", "title_hy": "Հեղուկը տաքանալիս սեղմվում է, իսկ սառչելիս՝ ընդարձակվում", "created_at": "2026-10-05T09:07:47.714385+00:00", "updated_at": "2026-10-05T18:40:48.53381+00:00", "description_hy": "Ջերմաչափի աշխատանքային տիրույթում հեղուկի ծավալի ջերմաստիճանային փոփոխության ուղղությունը մեկնաբանվում է հակառակ կերպ։"}, {"id": "c19b044f-781d-509c-90f7-daa75f64811e", "code": "scale_moves_liquid", "status": "active", "skill_id": "f5205906-522d-5fc8-b4e9-5762abf3109a", "title_hy": "Սանդղակն է շարժում հեղուկի սյունը", "created_at": "2026-10-05T09:07:47.714385+00:00", "updated_at": "2026-10-05T18:40:24.40359+00:00", "description_hy": "Սանդղակին վերագրվում է հեղուկը շարժելու դեր, մինչդեռ այն նախատեսված է միայն ցուցմունքները կարդալու (կամ գրանցելու) համար։"}, {"id": "e788d609-4ce0-5905-a759-464363b80381", "code": "capillary_blocks_liquid", "status": "active", "skill_id": "f5205906-522d-5fc8-b4e9-5762abf3109a", "title_hy": "Նեղ խողովակը թույլ չի տալիս հեղուկի անցումը", "created_at": "2026-10-05T09:07:47.714385+00:00", "updated_at": "2026-10-05T18:05:39.729029+00:00", "description_hy": "Մազական/Նեղ խողովակը խողովակը սխալմամբ համարվում է հեղուկի անցումն ամբողջությամբ արգելակող մաս։"}, {"id": "4a3bf402-c2e1-5b24-b2e2-16e7c6836f8a", "code": "thermometer_requires_boiling", "status": "active", "skill_id": "f5205906-522d-5fc8-b4e9-5762abf3109a", "title_hy": "Ջերմաչափն աշխատում է հեղուկի եռալու շնորհիվ", "created_at": "2026-10-05T09:07:47.714385+00:00", "updated_at": "2026-10-05T18:41:05.028847+00:00", "description_hy": "Հեղուկի սովորական ջերմային ընդարձակումը շփոթվում է եռման և գոլորշու ճնշման ազդեցության հետ։"}, {"id": "d136153f-b337-5f75-8e3b-bb4ce83002e8", "code": "liquid_volume_temperature_independent", "status": "active", "skill_id": "f5205906-522d-5fc8-b4e9-5762abf3109a", "title_hy": "Հեղուկի ծավալը կախված չէ ջերմաստիճանից", "created_at": "2026-10-05T09:07:47.714385+00:00", "updated_at": "2026-10-05T18:35:52.65762+00:00", "description_hy": "Հեղուկի ծավալը համարվում է անփոփոխ՝ անտեսելով ջերմաչափի աշխատանքի հիմքում ընկած ջերմային ընդարձակումը։"}, {"id": "ca98b089-6fb8-5f22-9161-ac83813e0246", "code": "cooling_causes_liquid_loss", "status": "active", "skill_id": "f5205906-522d-5fc8-b4e9-5762abf3109a", "title_hy": "Սառչելիս փակ ջերմաչափից հեղուկ է կորչում", "created_at": "2026-10-05T09:07:47.714385+00:00", "updated_at": "2026-10-05T18:08:08.817828+00:00", "description_hy": "Սյան իջնելը սխալմամբ բացատրվում է անվնաս փակ ջերմաչափից հեղուկի արտահոսքով, ոչ թե ծավալի փոքրացմամբ։"}, {"id": "02c5f5a3-98e5-5752-8c9b-0d1825fdb9e1", "code": "heating_creates_liquid", "status": "active", "skill_id": "f5205906-522d-5fc8-b4e9-5762abf3109a", "title_hy": "Տաքացնելիս ջերմաչափում նոր հեղուկ է առաջանում", "created_at": "2026-10-05T09:07:47.714385+00:00", "updated_at": "2026-10-05T18:35:33.237837+00:00", "description_hy": "Նույն հեղուկի ծավալի մեծացումը շփոթվում է լրացուցիչ հեղուկի առաջացման հետ։"}, {"id": "70976094-3a9c-5bea-9654-ed9054b54b79", "code": "wider_tube_gives_larger_rise", "status": "active", "skill_id": "f5205906-522d-5fc8-b4e9-5762abf3109a", "title_hy": "Լայն խողովակում նույն ծավալը ավելի մեծ բարձրություն է զբաղեցնում", "created_at": "2026-10-05T09:07:47.714385+00:00", "updated_at": "2026-10-05T18:52:03.363773+00:00", "description_hy": "Տրված ծավալի դեպքում խողովակի լայնության և սյան բարձրության փոփոխությունների կապը մեկնաբանվում է հակառակ կերպ։"}, {"id": "4988af9f-203d-5107-83ea-9d9258eaf576", "code": "tube_width_irrelevant", "status": "active", "skill_id": "f5205906-522d-5fc8-b4e9-5762abf3109a", "title_hy": "Խողովակի լայնությունը չի ազդում սյան բարձրության փոփոխության վրա", "created_at": "2026-10-05T09:07:47.714385+00:00", "updated_at": "2026-10-05T18:49:44.343306+00:00", "description_hy": "Հավասար ծավալային փոփոխություններին վերագրվում են հավասար բարձրության փոփոխություններ՝ անտեսելով խողովակների լայնական կտրվածքների տարբերությունը։"}]'::jsonb);
