review", "retired_reason": null, "difficulty_band": "core", "item_template_id": "64e056ae-e770-54f9-83f9-51ea3b09e6f5", "last_reviewed_at": null, "last_reviewed_by": null, "source_reference": "Գործող Ֆիզիկա 7 ծրագիր՝ Թեմա 2, լրացուցիչ վերջնարդյունք 2(2); Ֆիզիկա 7 (2023), Գլուխ II, §12, տպագիր էջեր 36-37, նկար 34", "validation_state": "provisional_no_sme_review", "variant_parameters": {"focusKey": "volume_not_new_liquid", "authoredCatalog": true, "evidencePurpose": "misconception_diagnosis"}, "replacement_item_id": null, "variant_fingerprint": "4e162399129d9d84452075789d19fa00"}, "options": [{"id": "554d6ef5-7e56-539d-a4b0-57d3c9bc0267", "item_id": "d3e27190-4689-54c0-ad03-f394db0c93d3", "content_en": null, "content_hy": "Տաքանալիս ներսում նոր սպիրտ է առաջանում, և դրա համար սյունը բարձրանում է։", "option_key": "A", "display_order": 1}, {"id": "cbfaffba-6b6f-536b-bfae-28e42e7bde12", "item_id": "d3e27190-4689-54c0-ad03-f394db0c93d3", "content_en": null, "content_hy": "Նոր հեղուկ չի առաջանում. սյունը բարձրանում է, որովհետև սպիրտը տաքանալիս սեղմվում է։", "option_key": "B", "display_order": 2}, {"id": "60afbbf5-4b02-5fc6-a9eb-fe523b398f38", "item_id": "d3e27190-4689-54c0-ad03-f394db0c93d3", "content_en": null, "content_hy": "Նոր հեղուկ չի առաջանում. նույն սպիրտը տաքանալիս ավելի մեծ ծավալ է զբաղեցնում։", "option_key": "C", "display_order": 3}, {"id": "e0b1b139-8bba-5efb-875f-caa2875569b5", "item_id": "d3e27190-4689-54c0-ad03-f394db0c93d3", "content_en": null, "content_hy": "Սպիրտի ծավալը չի փոխվում. սանդղակի բաժանումներն են հեղուկը քաշում վեր։", "option_key": "D", "display_order": 4}], "answerKey": {"answer": "C", "item_id": "d3e27190-4689-54c0-ad03-f394db0c93d3", "tolerance": null, "updated_at": "2026-10-05T09:07:47.714385+00:00", "feedback_code": "liquid_thermometer_operation", "accepted_units": [], "canonical_unit": null}, "misconceptions": [{"code": "heating_creates_liquid", "mappingNote": "Նույն հեղուկի ծավալի մեծացումը շփոթվում է լրացուցիչ հեղուկի առաջացման հետ։", "r