ingProfileVersion": "haiedu-evidence-blueprint-v1", "programmeOutcomeLocator": "7-րդ դասարան / Թեմա 2 / Վերջնարդյունքներ / Լրացուցիչ 2(2)", "answerPositionQaContract": "family-balanced-v1", "evidencePurposeRationaleHy": "Աշխատանքի սկզբունքը կիրառում է սառչող սենյակային ջերմաչափի սյան շարժումը կանխատեսելու և բացատրելու համար։"}, "status": "draft", "skill_id": "f5205906-522d-5fc8-b4e9-5762abf3109a", "stimulus": {}, "item_type": "single_choice", "prompt_en": null, "prompt_hy": "Սովորական սպիրտային սենյակային ջերմաչափը տաք սենյակից տեղափոխում են ավելի սառը սենյակ։ Ջերմաչափն անվնաս է, և ջերմաստիճանը նրա աշխատանքային տիրույթում է։ Երբ ջերմաչափը սառչի, ինչպե՞ս կփոխվի հեղուկի սյունը և ինչո՞ւ։", "created_at": "2026-10-05T09:07:47.714385+00:00", "difficulty": 2, "retired_at": null, "updated_at": "2026-10-05T09:07:47.714385+00:00", "version_no": 1, "item_family": "liquid_thermometer_operation", "variant_key": "liquid_thermometer_operation:02", "variant_seed": null, "review_status": "needs_review", "retired_reason": null, "difficulty_band": "core", "item_template_id": "64e056ae-e770-54f9-83f9-51ea3b09e6f5", "last_reviewed_at": null, "last_reviewed_by": null, "source_reference": "Գործող Ֆիզիկա 7 ծրագիր՝ Թեմա 2, լրացուցիչ վերջնարդյունք 2(2); Ֆիզիկա 7 (2023), Գլուխ II, §12, տպագիր էջեր 36-37, նկար 34", "validation_state": "provisional_no_sme_review", "variant_parameters": {"focusKey": "cooling_column_prediction", "authoredCatalog": true, "evidencePurpose": "application"}, "replacement_item_id": null, "variant_fingerprint": "e9c2844274a8c1e4972ce5ca8a1c2509"}, "options": [{"id": "94b8c421-4ab1-5ff4-b7ee-5c50644d623d", "item_id": "adb5d4a6-77e1-5a87-a0fb-4d9ed32dc328", "content_en": null, "content_hy": "Սյունը կբարձրանա, քանի որ սառչելիս սպիրտի ծավալը մեծանում է։", "option_key": "A", "display_order": 1}, {"id": "c31d75f0-1eb9-5cf5-aa1a-4a2169673488", "item_id": "adb5d4a6-77e1-5a87-a0fb-4d9ed32dc328", "content_en": null, "content_hy": "Սյունը կիջնի, քանի որ սառչելիս սպիրտի ծավալը փոքրանում է։", "option_key": "B", "display_order": 2}, {"id": "b9a12d5e-6fff-571a-83aa-604d3146c3ee", "item_id": "adb5d4a6-77e1-5a87-a0fb-4d9ed32dc328", "content_en": null, "content_hy": "Սյան բարձրությունը չի փոխվի, քանի որ սպիրտի ծավալը ջերմաստիճանից կախված չէ։", "option_key": "C", "display_order": 3}, {"id": "fc0ad418-7500-5079-8874-6a58c3a3d8ba", "item_id": "adb5d4a6-77e1-5a87-a0fb-4d9ed32dc328", "content_en": null, "content_hy": "Սյունը կիջնի, քանի որ սառչելիս սպիրտի մի մասը դուրս է գալիս փակ ջերմաչափից։", "option_key": "D", "display_order": 4}], "answerKey": {"answer": "B", "item_id": "adb5d4a6-77e1-5a87-a0fb-4d9ed32dc328", "tolerance": null, "updated_at": "2026-10-05T09:07:47.714385+00:00", "feedback_code": "liquid_thermometer_operation", "accepted_units": [], "canonical_unit": null}, "misconceptions": [{"code": "thermal_expansion_reversed", "mappingNote": "Ջերմաչափի աշխատանքային տիրույթում հեղուկի ծավալի ջերմաստիճանային փոփոխության ուղղությունը մեկնաբանվում է հակառակ կերպ։", "responseKey": "A"}, {"code": "liquid_volume_temperature_independent", "mappingNote": "Հեղուկի ծավալը համարվում է անփոփոխ՝ անտեսելով ջերմաչափի աշխատանքի հիմքում ընկած ջերմային ընդարձակումը։", "responseKey": "C"}, {"code": "cooling_causes_liquid_loss", "mappingNote": "Սյան իջնելը սխալմամբ բացատրվում է անվնաս փակ ջերմաչափից հեղուկի արտահոսքով, ոչ թե ծավալի փոքրացմամբ։", "responseKey": "D"}]}, "created_at": "2026-10-05T09:07:47.714385+00:00", "created_by": null, "version_no": 1, "change_summary": "15B.10 հեռանկարային ապացուցողական սխեմայով ութերորդ կառավարվող սևագիր ընտանիքի ստեղծում"}]'::jsonb);
