insert into public.item_template_remediation_guides select * from jsonb_populate_recordset(null::public.item_template_remediation_guides,'[{"id": "1cf26011-7afc-5da7-970e-ae4b6807bbb0", "status": "published", "metadata": {"sprint": "15B.10", "learnerVisible": false, "referenceMetadata": {"textbookSha256": "d8404d572f145d4afe924d0b8af900b3d9ed085a37893594667ab07a2ec12904", "textbookLocator": "Ֆիզիկա 7 (2023), Գլուխ II, §12, տպագիր էջեր 36-37, նկար 34", "programmeOutcomeLocator": "7-րդ դասարան / Թեմա 2 / Վերջնարդյունքներ / Լրացուցիչ 2(2)"}, "authoringProfileVersion": "haiedu-evidence-blueprint-v1"}, "title_hy": "Ինչպե՞ս է աշխատում հեղուկային ջերմաչափը", "hint_1_hy": "Նախ որոշի՛ր՝ հեղուկը տաքանո՞ւմ է, թե՞ սառչում։ Ինչպե՞ս է այդ դեպքում փոխվում դրա զբաղեցրած ծավալը։", "hint_2_hy": "Տաքանալիս հեղուկի ծավալը մեծանում է, և հեղուկը բարձրանում է խողովակով։ Սառչելիս տեղի է ունենում հակառակը։ Հիշի՛ր, որ հեղուկի նույն լրացուցիչ ծավալը նեղ խողովակում ավելի մեծ բարձրություն է զբաղեցնում, քան լայն խողովակում։", "created_at": "2026-10-05T09:07:47.714385+00:00", "updated_at": "2026-10-05T10:41:01.225657+00:00", "strategy_hy": "Երևույթների կապը դիտարկի՛ր հերթականությամբ. ջերմաստիճանի փոփոխություն, հեղուկի ծավալի փոփոխություն, ապա՝ սյան բարձրության փոփոխություն։ Իր աշխատանքային տիրույթում տաքանալիս հեղուկն ընդարձակվում է, իսկ սառչելիս՝ սեղմվում։ Քանի որ ջերմաչափը փակ է, դրանում հեղուկի քանակը չի փոխվում։ Նեղ մազական խողովակի շնորհիվ ծավալի փոքր փոփոխությունը հանգեցնում է սյան բարձրության նկատելի փոփոխության։ Սանդղակը միայն ցույց է տալիս ջերմաստիճանի արժեքը, բայց չի ազդում հեղուկի տեղաշարժի վրա։", "guide_version": 2, "item_template_id": "64e056ae-e770-54f9-83f9-51ea3b09e6f5", "worked_example_hy": "Օրինակ՝ սենյակային սպիրտային ջերմաչափը զով միջավայրից տեղափոխում են ավելի տաք միջավայր։ Տաքանալիս սպիրտի ծավալը մեծանում է, և դրա մի մասը պահեստարանից բարձրանում է մազական խողովակով։ Այս ընթացքում սպիրտի քանակը չի ավելանում. պարզապես նույն հեղուկն ավելի մեծ ծավալ է զբաղեցնում։ Երբ հեղուկի սյան բարձրությունը կայունանում է, ջերմաստիճանը որոշում են սանդղակի միջոցով։", "trigger_error_code": null, "allowed_parameter_keys": []}]'::jsonb);
