insert into skill_outcome_curriculum_mappings select * from jsonb_populate_recordset(null::public.skill_outcome_curriculum_mappings,'[{"skill_id": "f5205906-522d-5fc8-b4e9-5762abf3109a", "rationale": "Հմտությունը գնահատում է ջերմաչափի աշխատանքի սկզբունքի բացատրությունը՝ հեղուկային ջերմաչափի օրինակով։", "created_at": "2026-09-30T21:40:31.093879+00:00", "mapping_type": "direct", "reconciliation_id": "9af5bbd5-ffe7-5df7-a1a7-d911d11cfb1c", "learning_outcome_id": "cafad698-bc1d-53c0-9a8c-f00a034c0417"}]'::jsonb);
